changeSet.sql:
ALTER TABLE snippet RENAME TO sketch;
ALTER TABLE sketch RENAME COLUMN snippet_id TO sketch_id;
ALTER TABLE variation RENAME COLUMN snippet_id TO sketch_id;
ALTER TABLE note RENAME COLUMN snippet_id TO sketch_id;
ALTER TABLE wordcount_history RENAME COLUMN words_snippets TO words_sketches;

ALTER TABLE sketch RENAME CONSTRAINT snippet_pkey TO sketch_pkey;
ALTER TABLE sketch RENAME CONSTRAINT fk_snippet_user TO fk_sketch_user;
ALTER TABLE sketch RENAME CONSTRAINT fk_snippet_canon_variation TO fk_sketch_canon_variation;
ALTER TABLE variation RENAME CONSTRAINT fk_variation_snippet TO fk_variation_sketch;
ALTER TABLE note RENAME CONSTRAINT fk_note_snippet TO fk_note_sketch;

ALTER INDEX idx_snippet_user RENAME TO idx_sketch_user;
ALTER INDEX idx_variation_snippet_ordinal RENAME TO idx_variation_sketch_ordinal;
ALTER INDEX idx_variation_snippet_canon RENAME TO idx_variation_sketch_canon;
ALTER INDEX uq_note_snippet_live RENAME TO uq_note_sketch_live;
